// The C++ of Stash.Codec, ported from C# (CodeCoreMorph, D-78). K4os's LZ4Codec
// and XXH32/XXH64 are liblz4's and libxxhash's (the plan's dependency table): the same blocks
// and digests, byte for byte, but for an empty input, which K4os packs as no block at all.
#include "codec.hpp"

#include <lz4.h>
#include <lz4hc.h>
#include <xxhash.h>

#include <cstddef>
#include <limits>
#include <string>

namespace stash {
namespace {

int lz4_level(Effort effort) {
    switch (effort) {
        case Effort::Fast:
            return 0;
        case Effort::High:
            return 9;  // L09_HC
        case Effort::Max:
            return LZ4HC_CLEVEL_MAX;  // L12_MAX
    }
    throw ccm::ArgumentOutOfRangeException("effort");
}

void write_length(std::vector<std::uint8_t>& target, std::int32_t length) {
    auto bits = static_cast<std::uint32_t>(length);
    target[0] = static_cast<std::uint8_t>(bits);
    target[1] = static_cast<std::uint8_t>(bits >> 8);
    target[2] = static_cast<std::uint8_t>(bits >> 16);
    target[3] = static_cast<std::uint8_t>(bits >> 24);
}

std::int32_t read_length(const std::vector<std::uint8_t>& source) {
    std::uint32_t bits = static_cast<std::uint32_t>(source[0]) |
                         (static_cast<std::uint32_t>(source[1]) << 8) |
                         (static_cast<std::uint32_t>(source[2]) << 16) |
                         (static_cast<std::uint32_t>(source[3]) << 24);
    return static_cast<std::int32_t>(bits);  // C#'s int: the high bit is the sign
}

std::int32_t size_of(const std::vector<std::uint8_t>& data) {
    if (data.size() > static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max())) {
        throw ccm::ArgumentOutOfRangeException("data");
    }
    return static_cast<std::int32_t>(data.size());
}

}  // namespace

std::vector<std::uint8_t> Codec::pack(const std::vector<std::uint8_t>& data, Effort effort) {
    std::int32_t size = size_of(data);
    std::vector<std::uint8_t> packed(header_size + LZ4_compressBound(size));
    write_length(packed, size);
    int level = lz4_level(effort);
    int capacity = static_cast<int>(packed.size()) - header_size;
    const char* source = reinterpret_cast<const char*>(data.data());
    char* target = reinterpret_cast<char*>(packed.data() + header_size);
    int written = 0;
    if (size == 0) {
        written = 0;  // K4os writes no block for nothing; liblz4 would write one byte
    } else if (effort == Effort::Fast) {
        written = LZ4_compress_default(source, target, size, capacity);
    } else {
        written = LZ4_compress_HC(source, target, size, capacity, level);
    }
    if (written < 0 || (size != 0 && written == 0)) {
        throw ccm::InvalidOperationException("LZ4 couldn't encode the blob.");
    }
    packed.resize(static_cast<std::size_t>(header_size) + static_cast<std::size_t>(written));
    return packed;
}

std::vector<std::uint8_t> Codec::unpack(const std::vector<std::uint8_t>& packed) {
    if (packed.size() < static_cast<std::size_t>(header_size)) {
        throw InvalidDataException("A packed blob starts with its length.");
    }
    std::int32_t length = read_length(packed);
    if (length < 0) {
        throw InvalidDataException("A packed blob's length can't be negative.");
    }
    std::vector<std::uint8_t> data(static_cast<std::size_t>(length));
    int block = static_cast<int>(packed.size()) - header_size;
    int read = 0;
    if (block != 0) {
        read = LZ4_decompress_safe(reinterpret_cast<const char*>(packed.data() + header_size),
                                   reinterpret_cast<char*>(data.data()), block, length);
    }
    // K4os reads no block as nothing; liblz4 refuses an empty one.
    if (read < 0) {
        throw InvalidDataException("The blob's LZ4 block is corrupt.");
    }
    if (read != length) {
        throw InvalidDataException("The blob holds " + std::to_string(read) + " bytes, not the " +
                                   std::to_string(length) + " its header says.");
    }
    return data;
}

std::int32_t Codec::packed_bound(std::int32_t length) {
    if (length < 0) {
        throw ccm::ArgumentOutOfRangeException("length", "A length can't be negative.");
    }
    return header_size + LZ4_compressBound(length);
}

std::uint64_t Codec::checksum(const std::vector<std::uint8_t>& data) {
    return XXH64(data.data(), data.size(), 0);
}

std::uint32_t Codec::short_checksum(const std::vector<std::uint8_t>& data, std::uint32_t seed) {
    return XXH32(data.data(), data.size(), seed);
}

}  // namespace stash

