    static std::vector<std::uint8_t> unpack(const std::vector<std::uint8_t>& packed);
    // The most bytes pack can make of length.
    static std::int32_t packed_bound(std::int32_t length);
    static std::uint64_t checksum(const std::vector<std::uint8_t>& data);
    // A 32-bit checksum of data, seeded.
    static std::uint32_t short_checksum(const std::vector<std::uint8_t>& data, std::uint32_t seed);
};

