// The C++ of Stash.Store, ported from C# (CodeCoreMorph, D-78). Its ILogger is
// ccm::logging::ILogger (codecoremorph_logging.hpp), which the C# façade's logger implements
// through the bridge until the retirement.
#include "store.hpp"

#include <utility>

namespace stash {
namespace {

const ccm::logging::EventId& mismatch() {
    static const ccm::logging::EventId event{7, "ChecksumMismatch"};
    return event;
}

}  // namespace

Store::Store() : Store(nullptr, Effort::Fast) {}

Store::Store(std::shared_ptr<ccm::logging::ILogger> logger, Effort effort)
    : logger_(logger ? std::move(logger) : ccm::logging::NullLogger::instance()), effort_(effort) {}

std::shared_ptr<Store> Store::create(const std::shared_ptr<ccm::logging::ILoggerFactory>& factory,
                                     Effort effort) {
    if (!factory) throw ccm::ArgumentNullException("factory");
    return std::make_shared<Store>(factory->create_logger("Stash.Store"), effort);
}

std::int32_t Store::count() const { return static_cast<std::int32_t>(entries_.size()); }

std::int64_t Store::packed_bytes() const { return packed_bytes_; }

void Store::put(const std::string& key, const std::vector<std::uint8_t>& data) {
    std::vector<std::uint8_t> packed = Codec::pack(data, effort_);
    std::uint64_t sum = Codec::checksum(data);
    std::size_t size = packed.size();
    keep(key, Entry{std::move(packed), sum});
    ccm::logging::log_debug(*logger_, "Stored {Key}: {Raw} bytes in {Packed}", key, data.size(),
                            size);
}

std::vector<std::uint8_t> Store::get(const std::string& key) const {
    const Entry& entry = find(key);
    std::vector<std::uint8_t> data;
    try {
        data = Codec::unpack(entry.packed);
    } catch (const InvalidDataException& e) {
        ccm::logging::log_error(*logger_, e, "Blob {Key} doesn't unpack", key);
        throw;
    }
    if (Codec::checksum(data) != entry.sum) {
        ccm::logging::log_warning(*logger_, mismatch(), "Checksum mismatch for {Key}", key);
        throw InvalidDataException("The blob under '" + key + "' fails its checksum.");
    }
    return data;
}

bool Store::remove(const std::string& key) {
