using Sink = std::shared_ptr<std::vector<Logged>>;

// A logger that keeps what it logs, from min_level up.
class ListLogger : public ccm::logging::ILogger {
public:
    ListLogger(std::string category, Sink sink)
        : category_(std::move(category)), sink_(std::move(sink)) {}
    bool is_enabled(LogLevel level) const override { return level >= min_level; }
    void log(LogLevel level, const EventId& event, const std::string& message,
             const std::exception* exception) override {
        if (!is_enabled(level)) return;
        Logged logged{category_, level, event, message, {}, {}};
        if (exception != nullptr) {
            const auto* mirror = dynamic_cast<const ccm::Exception*>(exception);
            logged.exception_type = mirror != nullptr ? mirror->dotnet_type() : "System.Exception";
            logged.exception_message = exception->what();
        }
        sink_->push_back(std::move(logged));
    }
    const std::vector<Logged>& sink() const { return *sink_; }
    LogLevel min_level = LogLevel::Trace;

private:
    std::string category_;
    Sink sink_;
};

